127	+public class ServerDiscover extends Thread {
128	+	private static class ServerDiscoverListenerList extends ListenerList<IServerDiscoverListener>
129	+			implements IServerDiscoverListener {
130	+		@Override
131	+		public void onServerDiscovered(String host) {
132	+			for (IServerDiscoverListener listener : listeners()) {
133	+				listener.onServerDiscovered(host);
134	+			}
135	+		}
136	+		
137	+		@Override
138	+		public void onServerLost(String host) {
139	+			for (IServerDiscoverListener listener : listeners()) {
140	+				listener.onServerLost(host);
141	+			}
142	+		}
143	+	}
144	+	
145	+	private static final long MAX_SHOWN_DURATION = 3000;
146	+	
147	+	private volatile boolean _running;
148	+	private HashMap<String, Long> _knownServers;
149	+	
150	+	private ServerDiscoverListenerList _listenerList;
151	+	
152	+	public ServerDiscover() {
153	+		super("Server discover thread");
154	+		
155	+		_knownServers = new HashMap<String, Long>();
156	+		_listenerList = new ServerDiscoverListenerList();
157	+	}
158	+	
159	+	public ListenerList<IServerDiscoverListener> getListenerList() {
160	+		return _listenerList;
161	+	}
162	+	
163	+	public void stopDiscover() {
164	+		_running = false;
165	+	}
166	+	
167	+	@Override
168	+	public void run() {
169	+		_running = true;
170	+		Client client = new Client();
171	+		while (_running) {
172	+			List<InetAddress> servers = client.discoverHosts(PlayerNetwork.PLAYER_SERVICE_PORT,
173	+					1000);
174	+			for (InetAddress inetAddress : servers) {
175	+				String host = inetAddress.getHostAddress();
176	+				if (!_knownServers.containsKey(host)) {
177	+					_listenerList.onServerDiscovered(host);
178	+				}
179	+				_knownServers.put(host, System.currentTimeMillis());
180	+			}
181	+			
182	+			long minLastSeen = System.currentTimeMillis() - MAX_SHOWN_DURATION;
183	+			for (String host : _knownServers.keySet().toArray(new String[_knownServers.size()])) {
184	+				if (_knownServers.get(host) <= minLastSeen) {
185	+					_knownServers.remove(host);
186	+					_listenerList.onServerLost(host);
187	+				}
188	+			}
189	+		}
190	+	}
191	+}
